pageStyle:
*{box-sizing:border-box;}
        body{font-family:Arial, Helvetica, sans-serif; margin:0; padding:0}
        .f-row{display:flex;}
        .f-col{display:flex;flex-direction:column;}
        .f-row.v-center{align-items:center;}
        .f-row.h-center{justify-content:center;}
        .f-col.h-center{align-items: center;}
        .grow{flex:1;}
        .logo{max-width:300px;}
        input{width:100%; border:2px solid #3b3b3b; background: #eee; font-size: 16px; padding:10px; border-radius: 10px;}
        button{border:0; background:#3b3b3b; color:white; padding: 10px; font-size: 14px; border-radius: 10px; cursor: pointer;}
        .plot-title{font-size:18px;font-weight:bold;letter-spacing:-0.3px; border-radius: 20px;}
        .block{padding: 20px; box-shadow: rgba(0, 0, 0, 0.1) 0px 10px 15px -3px, rgba(0, 0, 0, 0.05) 0px 4px 6px -2px;}
        .bg{background: linear-gradient(180deg, gold, transparent);}
        .section-title {font-size: 20px;font-weight: bold;color: black;padding: 10px 5px;border-bottom: 3px solid gold;}
        .section-body {font-size: 14px;}
        .dataset-page-header{display:none}
        .kp-tabs-contents{display:none}
        .paper-footer-wrapper{display: none;}
        .col-md-12{padding:0;}
        .card-body{padding:0;}
        .mdkp-card{margin:0}
        .mdkp-body{padding:0;}
        .text-align-justify{text-align: justify;}
        .text-align-center{text-align:center;}
